            DefineSection("Scripts", async() => {
                WriteLiteral(@"
    <script>
        var section = [];
        $(""a[name='showMore']"").click(function (e) {
            var holder = parseInt($(e.currentTarget).data(""container""));
            section[holder] = (section[holder] ? section[holder] : 5) + 6;

            $(""#section_"" + holder).children().each(function () {
                var s = parseInt($(this).data(""serial""));
                if (s <= section[holder]) {
                    $(this).attr('hidden', false);
                }
            });
            var total = $(""#section_"" + holder).children().length;
            if (section[holder] >= total) {
                $(e.currentTarget).attr(""hidden"", true);
            }
        });
    </script>
");
            }
